const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{position:relative;overflow:hidden}\n.vs{position:absolute;inset:0;display:flex;flex-direction:column;gap:8px;padding:14px;min-width:0;min-height:0;color:var(--ink);font-size:13px;line-height:1.35;box-sizing:border-box}\n.vs *{box-sizing:border-box}\n.vs.s-3x3{padding:10px;gap:6px;font-size:12px}\n.vs.s-6x3{padding:12px}\nbutton,input,textarea{font:inherit;color:inherit;margin:0}\nbutton{cursor:pointer}\nbutton:disabled{opacity:.4;cursor:default}\nbutton:focus-visible,.inp:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.c1,.c2,.c3{display:-webkit-box;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}\n.c1{-webkit-line-clamp:1;line-clamp:1}\n.c2{-webkit-line-clamp:2;line-clamp:2}\n.c3{-webkit-line-clamp:3;line-clamp:3}\n.em{color:var(--muted);font-style:italic}\n\n.btn{height:34px;padding:0 12px;border-radius:10px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-weight:600;white-space:nowrap;min-width:0}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.btn.ghost{width:100%;border-style:dashed;color:var(--muted);font-weight:500}\n.s-3x3 .btn{height:30px;padding:0 8px}\n.ib{flex:none;width:30px;height:30px;padding:0;display:grid;place-items:center;border-radius:9px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:15px;line-height:1}\n.inp{width:100%;min-width:0;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);padding:7px 9px;outline:none}\n.inp:focus{border-color:var(--accent)}\ntextarea.inp{resize:none;display:block;min-height:56px;line-height:1.4}\n.s-6x3 textarea.inp{min-height:64px}\n.s-3x6 textarea.inp{min-height:96px}\n.s-6x6 textarea.inp{min-height:130px}\n\n.page{flex:1 1 0;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.s-3x3 .page{gap:6px}\n.top{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.top .inp{flex:1;height:30px;padding:3px 8px;font-weight:700}\n.top .btn{height:30px;padding:0 10px}\n.ttl{flex:1;min-width:0;font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sub{flex:none;font-size:11px;color:var(--muted)}\n.sub b{color:var(--accent);font-weight:800}\n.scroll{flex:1 1 0;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;scrollbar-width:thin}\n.foot{flex:none;display:flex;gap:6px}\n.foot .btn{flex:1 1 0}\n.hint{color:var(--muted);font-size:12px;line-height:1.5;padding:8px 2px}\n.err{flex:none;padding:5px 8px;border:1px solid var(--accent);border-radius:8px;background:var(--soft);font-size:12px;color:var(--ink)}\n.no{flex:none;width:20px;height:20px;border-radius:50%;background:var(--soft);color:var(--accent);font-size:11px;font-weight:700;display:grid;place-items:center}\n.cfm{display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid var(--accent);border-radius:10px;background:var(--soft);font-size:12px}\n.cfm.gap{margin-bottom:6px}\n.cbtn{display:flex;gap:6px}\n.cbtn .btn{flex:1 1 0}\n\n.home{flex:1 1 0;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.s-3x3 .home{gap:6px}\n.hd{flex:none;display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0}\n.tag{font-size:11px;font-weight:700;letter-spacing:.08em;color:var(--muted);white-space:nowrap}\n.chip{height:26px;padding:0 10px;border-radius:13px;border:1px solid var(--line);background:var(--soft);color:var(--ink);font-size:11px;font-weight:600;white-space:nowrap}\n.sum{flex:none;display:flex;flex-direction:column;gap:4px;min-width:0;padding:0;border:0;background:transparent;color:var(--ink);text-align:left}\n.s-3x3 .sum{flex:1 1 auto;min-height:0;justify-content:center}\n.sum .name{font-weight:700;font-size:15px;line-height:1.25}\n.s-3x3 .sum .name{font-size:14px}\n.s-6x6 .sum .name{font-size:20px}\n.dr{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;min-width:0}\n.dur{font-size:28px;font-weight:800;line-height:1.1;color:var(--accent);font-variant-numeric:tabular-nums;white-space:nowrap}\n.s-6x3 .dur,.s-3x6 .dur{font-size:30px}\n.s-6x6 .dur{font-size:40px}\n.cnt{font-size:12px;color:var(--muted);white-space:nowrap}\n.tl{flex:none;display:flex;gap:2px;height:8px;min-width:0}\n.seg{flex:1 1 0;min-width:2px;border-radius:3px}\n.seg.a{background:var(--accent)}\n.seg.b{background:var(--accent-alt)}\n.seg.z{background:var(--line)}\n.pv{flex:1 1 0;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;scrollbar-width:thin}\n.acts{flex:none;display:flex;gap:6px}\n.acts .btn{flex:1 1 0;padding:0 8px;overflow:hidden}\n.acts .btn.pri{flex:1.6 1 0}\n.pr{display:grid;grid-template-columns:20px minmax(0,1fr) auto;gap:6px;align-items:start;width:100%;padding:6px 2px;border:0;border-bottom:1px solid var(--line);background:transparent;text-align:left;color:var(--ink)}\n.pr .no{width:18px;height:18px;font-size:10px;margin-top:1px}\n.pr .tx{display:flex;flex-direction:column;gap:1px;min-width:0}\n.pr .v{font-weight:600}\n.pr .l{font-size:11px;color:var(--muted)}\n.pr .st{font-size:11px;font-weight:700;color:var(--accent);white-space:nowrap;font-variant-numeric:tabular-nums;margin-top:1px}\n.empty{flex:1 1 0;min-height:0;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;gap:8px}\n.empty .name{font-weight:700;font-size:16px}\n.empty p{margin:0;color:var(--muted);font-size:12px;line-height:1.5}\n.s-6x3 .home{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.25fr);grid-template-rows:auto minmax(0,1fr) auto auto;grid-template-areas:\"hd pv\" \"sum pv\" \"tl pv\" \"acts pv\";column-gap:12px;row-gap:6px}\n.s-6x3 .hd{grid-area:hd}\n.s-6x3 .sum{grid-area:sum;justify-content:center}\n.s-6x3 .tl{grid-area:tl}\n.s-6x3 .pv{grid-area:pv;border-left:1px solid var(--line);padding-left:10px}\n.s-6x3 .acts{grid-area:acts}\n\n.shot{display:grid;grid-template-columns:22px minmax(0,1fr) 30px 30px;column-gap:6px;row-gap:4px;align-items:center;padding:7px;margin-bottom:6px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.shot.moved{border-color:var(--accent);background:var(--soft)}\n.shot .t{font-size:11px;font-weight:700;color:var(--accent);font-variant-numeric:tabular-nums}\n.shot .body{grid-column:1 / -1;display:flex;flex-direction:column;gap:2px;min-width:0;padding:2px 0;border:0;background:transparent;text-align:left;color:var(--ink)}\n.mb{width:30px;height:24px;padding:0;border-radius:7px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:13px;line-height:1}\n.ln{display:grid;grid-template-columns:auto minmax(0,1fr);gap:6px;align-items:baseline;min-width:0}\n.ln.v{font-weight:600}\n.ln.l{color:var(--muted)}\n.k{font-size:10px;font-weight:700;color:var(--muted);letter-spacing:.04em}\n\n.fld{display:flex;flex-direction:column;gap:4px;margin-bottom:8px;min-width:0}\n.lab{font-size:11px;font-weight:700;color:var(--muted)}\n.s-6x3 .fgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.step{display:flex;align-items:center;gap:6px}\n.step .inp{width:84px;text-align:center}\n.unit{color:var(--muted)}\n\n.srow{display:flex;gap:6px;align-items:center;margin-bottom:6px}\n.srow .pick{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;padding:8px 10px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);text-align:left}\n.srow.on .pick{border-color:var(--accent);background:var(--soft)}\n.srow .nm{display:flex;align-items:center;gap:6px;min-width:0;font-weight:700}\n.srow .nmt{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.srow .mt{font-size:11px;color:var(--muted)}\n.srow .del{flex:none;height:30px;padding:0 8px}\n.now{flex:none;padding:0 6px;border-radius:8px;background:var(--accent);color:var(--on-accent);font-size:10px;font-weight:700;line-height:16px}\n";
function fmtDur(n){
  n=Math.round(Number(n)||0);
  if(n<60)return n+'秒';
  const m=Math.floor(n/60),r=n%60;
  return r?m+'分'+r+'秒':m+'分';
}
function shotsOf(sc){return sc&&Array.isArray(sc.shots)?sc.shots:[];}
function secsOf(x){const n=Number(x&&x.secs);return n>0?n:0;}
function sumSecs(sc){return shotsOf(sc).reduce(function(a,x){return a+secsOf(x);},0);}
function fmtDate(ts){if(!ts)return '';const d=new Date(ts);return (d.getMonth()+1)+'月'+d.getDate()+'日';}
function withScript(s,id,fn){
  const arr=s&&Array.isArray(s.scripts)?s.scripts:[];
  return Object.assign({},s,{scripts:arr.map(function(x){return x.id===id?Object.assign({},fn(x),{at:Date.now()}):x;})});
}
function recent(arr){return arr.slice().sort(function(a,b){return (b.at||0)-(a.at||0);});}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid}=ctx;
  const sz=ctx.size||'3x3';
  const h=function(tag,attrs,...c){
    const flat=[];
    c.forEach(function(x){
      if(Array.isArray(x)){x.forEach(function(y){if(y!=null&&y!==false)flat.push(y);});}
      else if(x!=null&&x!==false)flat.push(x);
    });
    return el(tag,attrs||{},...flat);
  };
  const list=Array.isArray(state&&state.scripts)?state.scripts.filter(function(x){return x&&x.id;}):[];
  const rec=recent(list);
  const sel=state&&state.selectedId;
  const cur=list.find(function(x){return x.id===sel;})||rec[0]||null;
  let view=ui.view||'home';
  if((view==='edit'||view==='shot')&&!cur)view='home';
  if(view==='shot'&&!ui.isNew&&!shotsOf(cur).some(function(x){return x.id===ui.sid;}))view='edit';
  const restore=[];
  const nu=function(v,extra){
    return Object.assign({view:v,sid:null,isNew:false,draft:null,err:'',confirm:'',scrollEdit:0,moved:null,from:'home',busy:false},extra||{});
  };
  const go=function(v,extra){
    Object.assign(ui,{view:v,err:'',confirm:'',moved:null,busy:false},extra||{});
    redraw();
  };
  const fail=function(msg){ui.busy=false;ui.err=msg;redraw();};
  const openShot=function(id,from){
    const x=shotsOf(cur).find(function(y){return y.id===id;});
    if(!x)return;
    go('shot',{sid:id,isNew:false,from:from,draft:{visual:x.visual||'',line:x.line||'',secs:x.secs==null?'':String(x.secs)}});
  };
  const newShot=function(from){go('shot',{sid:null,isNew:true,from:from,draft:{visual:'',line:'',secs:''}});};
  const newScript=function(from){go('new',{from:from,draft:{title:''}});};
  const move=function(id,dir){
    ui.moved=id;
    update(function(s){
      return withScript(s,cur.id,function(sc){
        const a=shotsOf(sc).slice();
        const i=a.findIndex(function(x){return x.id===id;});
        const j=i+dir;
        if(i<0||j<0||j>=a.length)return sc;
        const t=a[i];a[i]=a[j];a[j]=t;
        return Object.assign({},sc,{shots:a});
      });
    }).catch(function(){});
  };

  const saveShot=function(){
    if(ui.busy||!cur)return;
    const dr=ui.draft||{};
    const visual=String(dr.visual||'').trim();
    const line=String(dr.line||'').trim();
    const sv=String(dr.secs==null?'':dr.secs).trim();
    if(!visual&&!line&&sv===''){ui.err='请至少填写画面、台词或秒数中的一项';redraw();return;}
    let secs=null;
    if(sv!==''){
      const n=Number(sv);
      if(!isFinite(n)||n<0||n>36000){ui.err='秒数请填 0 到 36000 之间的数字';redraw();return;}
      secs=Math.round(n);
    }
    const sid=ui.sid,isNew=!!ui.isNew,id=cur.id;
    const nid=isNew?uid():sid;
    const back=ui.from==='home'?'home':'edit';
    const keep=isNew?10000000:(ui.scrollEdit||0);
    ui.busy=true;
    commit(function(s){
      return withScript(s,id,function(sc){
        const arr=shotsOf(sc);
        if(isNew)return Object.assign({},sc,{shots:arr.concat([{id:nid,visual:visual,line:line,secs:secs}])});
        return Object.assign({},sc,{shots:arr.map(function(x){
          return x.id===sid?Object.assign({},x,{visual:visual,line:line,secs:secs}):x;
        })});
      });
    },nu(back,{moved:nid,scrollEdit:keep})).catch(function(){fail('保存失败，请重试');});
  };
  const delShot=function(){
    if(ui.busy||!cur)return;
    const id=cur.id,sid=ui.sid,back=ui.from==='home'?'home':'edit';
    const keep=ui.scrollEdit||0;
    ui.busy=true;
    commit(function(s){
      return withScript(s,id,function(sc){
        return Object.assign({},sc,{shots:shotsOf(sc).filter(function(x){return x.id!==sid;})});
      });
    },nu(back,{scrollEdit:keep})).catch(function(){fail('删除失败，请重试');});
  };
  const pick=function(id){
    commit(function(s){return Object.assign({},s,{selectedId:id});},nu('home')).catch(function(){});
  };
  const delScript=function(id){
    if(ui.busy)return;
    ui.busy=true;
    commit(function(s){
      const arr=(s&&Array.isArray(s.scripts)?s.scripts:[]).filter(function(x){return x.id!==id;});
      let nsel=s&&s.selectedId;
      if(nsel===id||!arr.some(function(x){return x.id===nsel;})){
        const r=recent(arr)[0];
        nsel=r?r.id:null;
      }
      return Object.assign({},s,{scripts:arr,selectedId:nsel});
    },nu('list')).catch(function(){fail('删除失败，请重试');});
  };
  const createScript=function(){
    if(ui.busy)return;
    const t=String((ui.draft&&ui.draft.title)||'').trim();
    if(!t){ui.err='请先给脚本起个名字';redraw();return;}
    const nid=uid();
    ui.busy=true;
    commit(function(s){
      const arr=s&&Array.isArray(s.scripts)?s.scripts:[];
      return Object.assign({},s,{scripts:arr.concat([{id:nid,title:t,shots:[],at:Date.now()}]),selectedId:nid});
    },nu('edit')).catch(function(){fail('创建失败，请重试');});
  };

  function tlNode(sc){
    const shots=shotsOf(sc);
    const bar=h('div',{class:'tl','aria-hidden':'true'});
    if(!shots.length)bar.appendChild(h('span',{class:'seg z'}));
    shots.forEach(function(x,i){
      const seg=h('span',{class:'seg '+(i%2?'b':'a')});
      seg.style.flexGrow=String(secsOf(x)>0?secsOf(x):0.4);
      bar.appendChild(seg);
    });
    return bar;
  }
  function pvRow(x,i){
    return h('button',{class:'pr',type:'button',onclick:function(){openShot(x.id,'home');}},
      h('span',{class:'no'},String(i+1)),
      h('span',{class:'tx'},
        h('span',{class:'v '+(sz==='6x6'?'c2':'c1')+(x.visual?'':' em')},x.visual||'未填写画面'),
        x.line?h('span',{class:'l '+(sz==='6x6'?'c2':'c1')},x.line):null),
      h('span',{class:'st'},x.secs==null?'—':x.secs+'秒'));
  }
  function homeView(){
    if(!cur){
      return h('div',{class:'empty'},
        h('div',{class:'tag'},'视频脚本'),
        h('div',{class:'name'},'还没有脚本'),
        h('p',null,'新建一个脚本，逐个镜头写画面、台词和大概秒数，卡片上会显示总时长。'),
        h('button',{class:'btn pri',type:'button',onclick:function(){newScript('home');}},'新建脚本'));
    }
    const shots=shotsOf(cur),total=sumSecs(cur);
    const openEdit=function(){go('edit',{from:'home',scrollEdit:0});};
    const kids=[
      h('div',{class:'hd'},
        h('span',{class:'tag'},'视频脚本'),
        h('button',{class:'chip',type:'button',onclick:function(){go('list');}},sz==='3x3'?'切换':'切换脚本')),
      h('button',{class:'sum',type:'button',onclick:openEdit,'aria-label':'打开脚本：'+(cur.title||'未命名脚本')},
        h('span',{class:'name c2'},cur.title||'未命名脚本'),
        h('span',{class:'dr'},
          h('span',{class:'dur'},fmtDur(total)),
          h('span',{class:'cnt'},shots.length+' 个镜头'))),
      tlNode(cur)
    ];
    if(sz!=='3x3'){
      kids.push(h('div',{class:'pv'},
        shots.length?shots.map(pvRow):h('div',{class:'hint'},'还没有镜头，点「＋ 镜头」开始写。')));
    }
    kids.push(h('div',{class:'acts'},
      h('button',{class:'btn pri',type:'button',onclick:openEdit},'编写脚本'),
      sz==='3x3'?null:h('button',{class:'btn',type:'button',onclick:function(){newShot('home');}},'＋ 镜头')));
    return h('div',{class:'home'},kids);
  }

  function ln(k,txt,cls,n){
    return h('span',{class:'ln '+cls},
      h('span',{class:'k'},k),
      h('span',{class:'c'+n+(txt?'':' em')},txt||'未填写'));
  }
  function shotRow(x,i,arr){
    const n=sz==='6x6'?3:2;
    return h('div',{class:'shot'+(ui.moved===x.id?' moved':'')},
      h('span',{class:'no'},String(i+1)),
      h('span',{class:'t'},x.secs==null?'未估时':x.secs+'秒'),
      h('button',{class:'mb',type:'button',disabled:i===0,'aria-label':'镜头'+(i+1)+'上移',onclick:function(){move(x.id,-1);}},'↑'),
      h('button',{class:'mb',type:'button',disabled:i===arr.length-1,'aria-label':'镜头'+(i+1)+'下移',onclick:function(){move(x.id,1);}},'↓'),
      h('button',{class:'body',type:'button','aria-label':'编辑镜头'+(i+1),onclick:function(){openShot(x.id,'edit');}},
        ln('画面',x.visual,'v',n),
        ln('台词',x.line,'l',n)));
  }
  function editView(){
    const shots=shotsOf(cur),total=sumSecs(cur);
    const ti=h('input',{class:'inp',type:'text',maxlength:'40',placeholder:'脚本名称','aria-label':'脚本名称',
      onchange:function(e){
        const t=String(e.target.value||'').trim();
        if(!t){e.target.value=cur.title||'';return;}
        if(t!==cur.title){
          update(function(s){return withScript(s,cur.id,function(sc){return Object.assign({},sc,{title:t});});}).catch(function(){});
        }
      }});
    ti.value=cur.title||'';
    const body=h('div',{class:'scroll',onscroll:function(e){ui.scrollEdit=e.target.scrollTop;}},
      shots.length?shots.map(shotRow):h('div',{class:'hint'},'还没有镜头。点下方「添加镜头」，为每个镜头写画面、台词和大概秒数，再用 ↑ ↓ 调整顺序。'));
    restore.push(function(){body.scrollTop=ui.scrollEdit||0;});
    return h('div',{class:'page'},
      h('div',{class:'top'},
        h('button',{class:'ib',type:'button','aria-label':'返回',onclick:function(){go('home');}},'←'),
        ti),
      h('div',{class:'sub'},shots.length+' 个镜头 · 总时长 ',h('b',null,fmtDur(total))),
      body,
      h('div',{class:'foot'},h('button',{class:'btn pri',type:'button',onclick:function(){newShot('edit');}},'＋ 添加镜头')));
  }
  function shotView(){
    const dr=ui.draft||(ui.draft={visual:'',line:'',secs:''});
    const back=function(){go(ui.from==='home'?'home':'edit');};
    const ta=function(key,ph,label){
      const t=h('textarea',{class:'inp',rows:'3',placeholder:ph,'aria-label':label,oninput:function(e){dr[key]=e.target.value;}});
      t.value=dr[key]||'';
      return h('div',{class:'fld'},h('span',{class:'lab'},label),t);
    };
    const sec=h('input',{class:'inp',type:'number',min:'0',max:'36000',step:'1',placeholder:'如 5','aria-label':'大概秒数',
      oninput:function(e){dr.secs=e.target.value;}});
